 state.auth.state='login_required';state.auth.message='尚未登录';state.auth.renewal={prepared:true,message:'登录维护已准备，等待官方授权'};
 $('ck-sub-refresh').click();await wait(()=>$('ck-sub-state').textContent==='尚未登录订阅');
